changeSet.sql:
ALTER TABLE financial.wallet_entries
    ADD COLUMN id_compartment_movement bigint;
ALTER TABLE financial.wallet_entries
    ADD CONSTRAINT fk_compartment_movements_on_wallet_entries FOREIGN KEY (id_compartment_movement) REFERENCES financial.compartment_movements (id) ON DELETE CASCADE;
CREATE INDEX ix_wallet_entries_on_compartment_movement ON financial.wallet_entries (id_compartment_movement);
ALTER TABLE financial.wallet_entries
    DROP CONSTRAINT ck_wallet_entries_on_origin;
ALTER TABLE financial.wallet_entries
    ADD CONSTRAINT ck_wallet_entries_on_origin CHECK (
        origin IN ('INCOME', 'EXPENSE', 'REVERSAL', 'ADJUSTMENT', 'TRANSFER', 'INVOICE_PAYMENT', 'COMPARTMENT')
    );

rollback.sql:
DELETE FROM financial.wallet_entries WHERE origin = 'COMPARTMENT';
ALTER TABLE financial.wallet_entries
    DROP CONSTRAINT ck_wallet_entries_on_origin;
ALTER TABLE financial.wallet_entries
    ADD CONSTRAINT ck_wallet_entries_on_origin CHECK (
        origin IN ('INCOME', 'EXPENSE', 'REVERSAL', 'ADJUSTMENT', 'TRANSFER', 'INVOICE_PAYMENT')
    );
DROP INDEX financial.ix_wallet_entries_on_compartment_movement;
ALTER TABLE financial.wallet_entries
    DROP CONSTRAINT fk_compartment_movements_on_wallet_entries;
ALTER TABLE financial.wallet_entries
    DROP COLUMN id_compartment_movement;
